import type { AgentArtifact, AgentNamespace, VaultManifest } from "./types";
import {
  DB_NAME, DB_VERSION, STORE_ARTIFACTS, STORE_MANIFEST,
  LOCAL_MAX_ARTIFACTS, LOCAL_MAX_BYTES,
} from "./constants";

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onerror = () => reject(req.error);
    req.onsuccess = () => resolve(req.result);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_ARTIFACTS)) {
        const store = db.createObjectStore(STORE_ARTIFACTS, { keyPath: "id" });
        store.createIndex("agent", "agent", { unique: false });
        store.createIndex("updatedAt", "updatedAt", { unique: false });
      }
      if (!db.objectStoreNames.contains(STORE_MANIFEST)) {
        db.createObjectStore(STORE_MANIFEST, { keyPath: "vaultId" });
      }
    };
  });
}

function tx<T>(
  storeName: string,
  mode: IDBTransactionMode,
  fn: (store: IDBObjectStore) => IDBRequest<T>,
): Promise<T> {
  return openDb().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const t = db.transaction(storeName, mode);
        const store = t.objectStore(storeName);
        const req = fn(store);
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
        t.oncomplete = () => db.close();
        t.onerror = () => reject(t.error);
      }),
  );
}

export function uid(): string {
  return crypto.randomUUID?.() ?? `tl-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function estimateBytes(obj: unknown): number {
  try {
    return new Blob([JSON.stringify(obj)]).size;
  } catch {
    return 0;
  }
}

export async function saveLocalArtifact<T>(artifact: AgentArtifact<T>): Promise<void> {
  await tx(STORE_ARTIFACTS, "readwrite", (s) => s.put(artifact));
  await pruneLocalIfNeeded();
}

export async function getLocalArtifact<T>(id: string): Promise<AgentArtifact<T> | null> {
  try {
    return await tx(STORE_ARTIFACTS, "readonly", (s) => s.get(id));
  } catch {
    return null;
  }
}

export async function listLocalByAgent<T>(agent: AgentNamespace): Promise<AgentArtifact<T>[]> {
  try {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const t = db.transaction(STORE_ARTIFACTS, "readonly");
      const idx = t.objectStore(STORE_ARTIFACTS).index("agent");
      const req = idx.getAll(agent);
      req.onsuccess = () => {
        const rows = (req.result as AgentArtifact<T>[]).sort(
          (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
        );
        db.close();
        resolve(rows);
      };
      req.onerror = () => { db.close(); reject(req.error); };
    });
  } catch {
    return [];
  }
}

export async function deleteLocalArtifact(id: string): Promise<void> {
  await tx(STORE_ARTIFACTS, "readwrite", (s) => s.delete(id));
}

export async function getLocalStats(): Promise<{ count: number; bytes: number; byAgent: Record<string, number> }> {
  try {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const t = db.transaction(STORE_ARTIFACTS, "readonly");
      const req = t.objectStore(STORE_ARTIFACTS).getAll();
      req.onsuccess = () => {
        const rows = req.result as AgentArtifact[];
        const byAgent: Record<string, number> = {};
        let bytes = 0;
        for (const r of rows) {
          bytes += r.sizeBytes ?? 0;
          byAgent[r.agent] = (byAgent[r.agent] ?? 0) + 1;
        }
        db.close();
        resolve({ count: rows.length, bytes, byAgent });
      };
      req.onerror = () => { db.close(); reject(req.error); };
    });
  } catch {
    return { count: 0, bytes: 0, byAgent: {} };
  }
}

async function pruneLocalIfNeeded(): Promise<void> {
  const stats = await getLocalStats();
  if (stats.count <= LOCAL_MAX_ARTIFACTS && stats.bytes <= LOCAL_MAX_BYTES) return;

  const db = await openDb();
  await new Promise<void>((resolve, reject) => {
    const t = db.transaction(STORE_ARTIFACTS, "readwrite");
    const store = t.objectStore(STORE_ARTIFACTS);
    const idx = store.index("updatedAt");
    const req = idx.openCursor();
    const toDelete: string[] = [];
    let count = stats.count;
    req.onsuccess = () => {
      const cursor = req.result;
      if (!cursor) {
        for (const id of toDelete) store.delete(id);
        return;
      }
      if (count > LOCAL_MAX_ARTIFACTS) {
        toDelete.push((cursor.value as AgentArtifact).id);
        count--;
      }
      cursor.continue();
    };
    t.oncomplete = () => { db.close(); resolve(); };
    t.onerror = () => { db.close(); reject(t.error); };
  });
}

export async function saveVaultManifest(manifest: VaultManifest): Promise<void> {
  await tx(STORE_MANIFEST, "readwrite", (s) => s.put(manifest));
}

export async function getVaultManifest(vaultId: string): Promise<VaultManifest | null> {
  try {
    return await tx(STORE_MANIFEST, "readonly", (s) => s.get(vaultId));
  } catch {
    return null;
  }
}

export async function clearAllLocal(): Promise<number> {
  const stats = await getLocalStats();
  const db = await openDb();
  await new Promise<void>((resolve, reject) => {
    const t = db.transaction([STORE_ARTIFACTS, STORE_MANIFEST], "readwrite");
    t.objectStore(STORE_ARTIFACTS).clear();
    t.objectStore(STORE_MANIFEST).clear();
    t.oncomplete = () => { db.close(); resolve(); };
    t.onerror = () => { db.close(); reject(t.error); };
  });
  return stats.count;
}
