import type { AgentArtifact, VaultManifest } from "./types";
import {
  GIST_MAX_FILES, GIST_SHARD_SOFT_LIMIT, VAULT_GIST_DESCRIPTION,
  LS_VAULT_MANIFEST,
} from "./constants";
import { estimateBytes, uid } from "./indexed-store";

const GIST_API = "https://api.github.com/gists";

function ghHeaders(token: string): HeadersInit {
  return {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${token}`,
    "User-Agent": "ThreatLens-FreeStorage/1.0",
    "X-GitHub-Api-Version": "2022-11-28",
  };
}

export function gistFileName(agent: string, id: string): string {
  return `${agent}__${id.replace(/-/g, "").slice(0, 12)}.json`;
}

export function loadManifestFromLs(): VaultManifest | null {
  try {
    const raw = localStorage.getItem(LS_VAULT_MANIFEST);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export function saveManifestToLs(manifest: VaultManifest): void {
  localStorage.setItem(LS_VAULT_MANIFEST, JSON.stringify(manifest));
}

export function createEmptyManifest(): VaultManifest {
  const vaultId = uid();
  const now = new Date().toISOString();
  return {
    version: 1,
    vaultId,
    createdAt: now,
    updatedAt: now,
    index: {},
    gistBytes: 0,
  };
}

export async function testGistToken(token: string): Promise<{ ok: boolean; login?: string; error?: string }> {
  try {
    const res = await fetch("https://api.github.com/user", { headers: ghHeaders(token) });
    if (!res.ok) return { ok: false, error: `GitHub auth failed (${res.status})` };
    const user = await res.json();
    return { ok: true, login: user.login };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

async function createVaultGist(token: string, manifest: VaultManifest): Promise<string | null> {
  const res = await fetch(GIST_API, {
    method: "POST",
    headers: { ...ghHeaders(token), "Content-Type": "application/json" },
    body: JSON.stringify({
      description: VAULT_GIST_DESCRIPTION,
      public: false,
      files: {
        "manifest.json": { content: JSON.stringify(manifest, null, 2) },
      },
    }),
  });
  if (!res.ok) return null;
  const data = await res.json();
  return data.id ?? null;
}

async function patchGist(
  token: string,
  gistId: string,
  files: Record<string, { content: string } | null>,
): Promise<boolean> {
  const res = await fetch(`${GIST_API}/${gistId}`, {
    method: "PATCH",
    headers: { ...ghHeaders(token), "Content-Type": "application/json" },
    body: JSON.stringify({ files }),
  });
  return res.ok;
}

export async function uploadArtifactToGist<T>(
  token: string,
  manifest: VaultManifest,
  artifact: AgentArtifact<T>,
): Promise<{ manifest: VaultManifest; gistId: string } | null> {
  let gistId = manifest.gistId;
  const fileName = gistFileName(artifact.agent, artifact.id);
  const content = JSON.stringify(artifact);
  const fileBytes = estimateBytes(artifact);

  const needsNewShard =
    !gistId ||
    manifest.gistBytes + fileBytes > GIST_SHARD_SOFT_LIMIT ||
    Object.values(manifest.index).flat().length >= GIST_MAX_FILES;

  if (needsNewShard && gistId) {
    manifest = {
      ...createEmptyManifest(),
      prevGistId: gistId,
      index: { ...manifest.index },
    };
    gistId = undefined;
  }

  if (!gistId) {
    const newId = await createVaultGist(token, manifest);
    if (!newId) return null;
    gistId = newId;
    manifest.gistId = gistId;
    manifest.gistBytes = estimateBytes(manifest);
  }

  const ok = await patchGist(token, gistId, {
    [fileName]: { content },
    "manifest.json": { content: JSON.stringify(manifest, null, 2) },
  });
  if (!ok) return null;

  manifest.gistId = gistId;
  manifest.gistBytes += fileBytes;
  manifest.updatedAt = new Date().toISOString();
  saveManifestToLs(manifest);
  return { manifest, gistId };
}

export async function pullFromGist<T>(
  token: string,
  gistId: string,
  fileName: string,
): Promise<AgentArtifact<T> | null> {
  try {
    const res = await fetch(`${GIST_API}/${gistId}`, { headers: ghHeaders(token) });
    if (!res.ok) return null;
    const gist = await res.json();
    const file = gist.files?.[fileName];
    if (!file?.content) return null;
    return JSON.parse(file.content) as AgentArtifact<T>;
  } catch {
    return null;
  }
}

export async function syncManifestFromGist(token: string, gistId: string): Promise<VaultManifest | null> {
  try {
    const res = await fetch(`${GIST_API}/${gistId}`, { headers: ghHeaders(token) });
    if (!res.ok) return null;
    const gist = await res.json();
    const raw = gist.files?.["manifest.json"]?.content;
    if (!raw) return null;
    const manifest = JSON.parse(raw) as VaultManifest;
    manifest.gistId = gistId;
    saveManifestToLs(manifest);
    return manifest;
  } catch {
    return null;
  }
}

export function updateManifestIndex(manifest: VaultManifest, artifact: AgentArtifact): VaultManifest {
  const list = manifest.index[artifact.agent] ?? [];
  const next = [artifact.id, ...list.filter((id) => id !== artifact.id)].slice(0, 200);
  return {
    ...manifest,
    index: { ...manifest.index, [artifact.agent]: next },
    updatedAt: new Date().toISOString(),
  };
}
